        await projectVault(config);
      } catch (renderError) {
        projectionStatus = "pending";
        projectionError = renderError;
      }
      return {
        book,
        result,
        projectionStatus,
        ...(projectionError !== undefined ? { projectionError } : {}),
      };
    } finally {
      release();
      if (bookQueues.get(queueKey) === queued) bookQueues.delete(queueKey);
    }
